    const id=clean(q.id||`q${i+1}`,90),text=clean(q.text,1000),options=Array.isArray(q.options)?q.options.map(o=>clean(o,300)):[];
    const correct=Number(q.correct), seconds=Number(q.seconds??(q.kind==='theory'?15:30));
    if(!id||ids.has(id)||!text||options.length!==4||options.some(o=>!o)||new Set(options).size!==4||!Number.isInteger(correct)||correct<0||correct>3||!Number.isInteger(seconds)||seconds<5||seconds>120) fail('question',`${i+1}-сұрақты тексер: мәтін, төрт түрлі нұсқа, бір дұрыс жауап және 5–120 секунд қажет.`);
