    if(!Number.isInteger(round)||round<1||round>10||numbers.has(round))fail('round_number','Кезең нөмірі 1–10 аралығында және қайталанбайтын болуы керек.');
    const questions=validateQuestions(r.questions);
    for(const q of questions){const key=questionKey(q);if(used.has(key))fail('repeated_round_question',`«${q.text.slice(0,65)}» бірнеше кезеңде қайталанып тұр. Әр кезеңге бөлек сұрақ бер.`);used.add(key);}
