      if(payload.mode!==undefined){if(!['single','tournament'].includes(payload.mode))fail('mode','Ойын режимін таңда.');room.mode=payload.mode;}
      if(payload.game!==undefined){if(!['tug','castle'].includes(payload.game))fail('game','Ойын түрін таңда.');room.game=payload.game;}
      if(payload.names!==undefined){if(!Array.isArray(payload.names)||payload.names.length!==2||payload.names.some(n=>clean(n,22).length<1))fail('names','Екі команданың атауын енгіз.');room.names=payload.names.map(n=>clean(n,22));}
