const SCHEMA='CREATE TABLE IF NOT EXISTS classroom_rooms(code TEXT PRIMARY KEY,version INTEGER NOT NULL,state TEXT NOT NULL,expires_at INTEGER NOT NULL); CREATE INDEX IF NOT EXISTS rooms_expiry ON classroom_rooms(expires_at);';
function createApplication({databasePath=path.join(path.dirname(fileURLToPath(import.meta.url)),'.data/rooms.sqlite'),clock=Date.now,random=Math.random}={}){
  if(databasePath!==':memory:')mkdirSync(path.dirname(databasePath),{recursive:true});
  const db=new DatabaseSync(databasePath);db.exec(SCHEMA);db.exec('PRAGMA journal_mode=WAL');
  db.prepare('DELETE FROM classroom_rooms WHERE expires_at<=?').run(clock());
  const get=db.prepare('SELECT state FROM classroom_rooms WHERE code=?'),insert=db.prepare('INSERT OR IGNORE INTO classroom_rooms(code,version,state,expires_at) VALUES(?,?,?,?)'),update=db.prepare('UPDATE classroom_rooms SET state=?,version=?,expires_at=? WHERE code=? AND version=?');
  const store={async get(code){const row=get.get(code);return row?JSON.parse(row.state):null;},async insert(room){return insert.run(room.code,room.version,JSON.stringify(room),room.expiresAt).changes===1;},async compareAndSwap(code,version,room){return update.run(JSON.stringify(room),room.version,room.expiresAt,code,version).changes===1;}};
  const api=createApi(store,{clock,random}),mime={'.html':'text/html; charset=utf-8','.css':'text/css; charset=utf-8','.mjs':'text/javascript; charset=utf-8','.svg':'image/svg+xml','.json':'application/json; charset=utf-8','.pdf':'application/pdf','.xlsx':'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'};
  return {async fetch(request){
    const url=new URL(request.url);if(url.pathname.startsWith('/api/'))return api(request);
    if(!['GET','HEAD'].includes(request.method))return new Response('Method not allowed',{status:405});
    const key=['/','/join'].includes(url.pathname)?'/index.html':url.pathname,asset=WEB_ASSETS[key];
    if(asset===undefined)return new Response('Not found',{status:404});
    const data=typeof asset==='string'?asset:Buffer.from(asset.base64,'base64');
    const headers={'Content-Type':mime[path.extname(key)]||'application/octet-stream','Cache-Control':'no-cache','X-Content-Type-Options':'nosniff','Referrer-Policy':'same-origin','X-Frame-Options':'SAMEORIGIN'};
    if(key.startsWith('/templates/'))headers['Content-Disposition']='attachment; filename="'+path.basename(key)+'"';
    return new Response(request.method==='HEAD'?null:data,{headers});
  },close(){db.close();}};
}
function startServer(){
  const app=createApplication(),port=Number(process.env.PORT)||4174,host=process.env.HOST||(process.env.PORT?'0.0.0.0':'127.0.0.1');
  const server=createServer(async(req,res)=>{
    try{
      const chunks=[];let size=0;for await(const chunk of req){size+=chunk.length;if(size>2000000){res.writeHead(413);res.end('Request too large');return;}chunks.push(chunk);}
      const protocol=req.headers['x-forwarded-proto']==='https'?'https':'http',origin=process.env.PUBLIC_ORIGIN||protocol+'://'+(req.headers.host||'localhost:'+port);
      const request=new Request(new URL(req.url,origin),{method:req.method,headers:req.headers,body:['GET','HEAD'].includes(req.method)?undefined:Buffer.concat(chunks)});
      const response=await app.fetch(request);res.writeHead(response.status,Object.fromEntries(response.headers));res.end(Buffer.from(await response.arrayBuffer()));
    }catch(error){console.error('HTTP error',error);res.writeHead(500);res.end('Server error');}
  });
  let closing=false;const shutdown=()=>{if(closing)return;closing=true;server.close(()=>{app.close();process.exit(0);});};process.once('SIGTERM',shutdown);process.once('SIGINT',shutdown);
  server.listen(port,host,()=>console.log('Arqan Tartys v3 listening on '+host+':'+port));return {server,app};
}
if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url))startServer();


export { createApplication, createApi, startServer };
